package beer

import (
	"errors"
	"fmt"
	"strings"
)

// bottlesPhrase returns the phrase for the given number of bottles,
// e.g. "99 bottles of beer", "1 bottle of beer", or "no more bottles of beer".
func bottlesPhrase(n int) string {
	switch n {
	case 0:
		return "no more bottles of beer"
	case 1:
		return "1 bottle of beer"
	default:
		return fmt.Sprintf("%d bottles of beer", n)
	}
}

// Verse returns the lyrics of the verse for the given number of bottles.
func Verse(n int) (string, error) {
	if n < 0 || n > 99 {
		return "", errors.New("verse number must be between 0 and 99")
	}

	if n == 0 {
		return "No more bottles of beer on the wall, no more bottles of beer.\n" +
			"Go to the store and buy some more, 99 bottles of beer on the wall.\n", nil
	}

	action := "Take one down"
	if n == 1 {
		action = "Take it down"
	}

	return fmt.Sprintf("%s on the wall, %s.\n%s and pass it around, %s on the wall.\n",
		capitalize(bottlesPhrase(n)), bottlesPhrase(n), action, bottlesPhrase(n-1)), nil
}

// Verses returns the lyrics of the verses from start down to stop, inclusive.
func Verses(start, stop int) (string, error) {
	if start < stop || start > 99 || stop < 0 {
		return "", errors.New("invalid verse range")
	}

	var sb strings.Builder
	for n := start; n >= stop; n-- {
		verse, err := Verse(n)
		if err != nil {
			return "", err
		}
		sb.WriteString(verse)
		sb.WriteString("\n")
	}
	return sb.String(), nil
}

// Song returns the lyrics of the entire song.
func Song() string {
	song, err := Verses(99, 0)
	if err != nil {
		// Unreachable: Verses(99, 0) is always a valid range.
		panic(err)
	}
	return song
}

// capitalize uppercases the first rune of s.
func capitalize(s string) string {
	if s == "" {
		return s
	}
	runes := []rune(s)
	runes[0] = []rune(strings.ToUpper(string(runes[0])))[0]
	return string(runes)
}

